def read_baseline(text):
    df = pd.read_csv(
        io.StringIO(text)
    )

    for col in [
        "entry_time_utc",
        "exit_time_utc",
    ]:
        df[col] = pd.to_datetime(
            df[col],
            utc=True,
        )

    df["result_r"] = pd.to_numeric(
        df["result_r"],
        errors="coerce",
    )

    return df


def candidate_df(
    trades,
):
    return pd.DataFrame([
        {
            "instrument":
                "GBP_USD",
            "side":
                "BUY",
            "strategy":
                trade[
                    "candidate_id"
                ],
            "entry_time_utc":
                trade[
                    "signal_time"
                ],
            "exit_time_utc":
                trade[
                    "exit_time"
                ],
            "reference_entry":
                trade[
                    "reference_entry"
                ],
            "backtest_entry":
                trade[
                    "backtest_entry"
                ],
            "stop":
                trade["stop"],
            "target":
                trade["target"],
            "exit_reason":
                trade[
                    "exit_reason"
                ],
            "result_r":
                trade["result_r"],
            "reward_risk":
                REWARD_RISK,
        }
        for trade in trades
    ])


def restrict_window(
    df,
    start,
    end,
):
    return df[
        (
            df["entry_time_utc"]
            >= start
        )
        &
        (
            df["entry_time_utc"]
            <= end
        )
    ].copy()


def substitute(
    baseline,
    incoming,
):
    start = baseline[
        "entry_time_utc"
    ].min()

    end = baseline[
        "entry_time_utc"
    ].max()

    kept = baseline[
        ~(
            (
                baseline["instrument"]
                == "GBP_USD"
            )
            &
            (
                baseline["side"]
                == "BUY"
            )
        )
    ].copy()

    incoming = restrict_window(
        incoming,
        start,
        end,
    )

    return (
        pd.concat(
            [
                kept,
                incoming,
            ],
            ignore_index=True,
        )
        .sort_values(
            [
                "entry_time_utc",
                "exit_time_utc",
                "instrument",
                "side",
            ]
        )
        .reset_index(
            drop=True
        )
    )


def simple_stats(df):
    r = df[
        "result_r"
    ].astype(float)

    winners = r[
        r > 0
    ]

    losers = r[
        r < 0
    ]

    gp = winners.sum()
    gl = abs(
        losers.sum()
    )

    if gl > 0:
        pf = gp / gl
    elif gp > 0:
        pf = 999.0
    else:
        pf = 0.0

    total = r.sum()

    return {
        "trades":
            len(df),
        "winners":
            len(winners),
        "losers":
            len(losers),
        "win_rate":
            (
                len(winners)
                / len(df)
                * 100.0
                if len(df)
                else 0.0
            ),
        "profit_factor":
            pf,
        "total_r":
            total,
        "expectancy_r":
            (
                total
                / len(df)
                if len(df)
                else 0.0
            ),
    }


def compound(
    df,
    starting_balance=100.0,
    risk_percent=0.01,
):
    records = (
        df.reset_index(drop=True)
        .to_dict("records")
    )

    events = []

    for i, trade in enumerate(records):
        events.append((
            pd.Timestamp(
                trade[
                    "entry_time_utc"
                ]
            ).to_pydatetime(),
            1,
            "ENTRY",
            i,
        ))

        events.append((
            pd.Timestamp(
                trade[
                    "exit_time_utc"
                ]
            ).to_pydatetime(),
            0,
            "EXIT",
            i,
        ))

    # EXIT before ENTRY at equal timestamps.
    events.sort(
        key=lambda x: (
            x[0],
            x[1],
        )
    )

    balance = float(
        starting_balance
    )

    risk_at_entry = {}

    peak = balance
    max_dd_pct = 0.0

    for (
        event_time,
        priority,
        event_type,
        i,
    ) in events:
        trade = records[i]

        if event_type == "ENTRY":
            risk_at_entry[i] = (
                balance
                * risk_percent
            )

        else:
            risk_amount = (
                risk_at_entry.get(i)
            )

            if risk_amount is None:
                continue

            balance += (
                risk_amount
                * float(
                    trade[
                        "result_r"
                    ]
                )
            )

            peak = max(
                peak,
                balance,
            )

            if peak > 0:
                dd = (
                    (
                        balance
                        - peak
                    )
                    / peak
                    * 100.0
                )

                max_dd_pct = min(
                    max_dd_pct,
                    dd,
                )

    return {
        "ending_balance":
            balance,
        "return_pct":
            (
                balance
                / starting_balance
                - 1.0
            ) * 100.0,
        "max_closed_equity_dd_pct":
            max_dd_pct,
    }


def portfolio_row(
    window,
    cfg,
    portfolio,
    incoming_count,
    baseline_metrics,
):
    s = simple_stats(
        portfolio
    )

    c = compound(
        portfolio
    )

    return {
        "window":
            window,
        "candidate_id":
            cfg["id"],
        "structure_lookback":
            cfg[
                "structure_lookback"
            ],
        "maximum_distance_atr":
            cfg[
                "maximum_distance_atr"
            ],
        "minimum_body_atr":
            cfg[
                "minimum_body_atr"
            ],
        "minimum_body_ratio":
            cfg[
                "minimum_body_ratio"
            ],
        "session":
            cfg["session"],
        "candidate_trades_in_window":
            incoming_count,

        "standalone_full_history_trades":
            cfg[
                "standalone_trades"
            ],
        "standalone_full_history_pf":
            cfg[
                "standalone_pf"
            ],
        "standalone_full_history_total_r":
            cfg[
                "standalone_total_r"
            ],
        "standalone_full_history_expectancy_r":
            cfg[
                "standalone_expectancy_r"
            ],
        "standalone_full_history_max_dd_r":
            cfg[
                "standalone_max_dd_r"
            ],
        "standalone_full_history_loss_streak":
            cfg[
                "standalone_loss_streak"
            ],
        "standalone_worst_era_pf":
            cfg[
                "standalone_worst_era_pf"
            ],
        "standalone_worst_rolling_3y_pf":
            cfg[
                "standalone_worst_rolling_3y_pf"
            ],

        "portfolio_trades":
            s["trades"],
        "portfolio_win_rate":
            round(
                s["win_rate"],
                6,
            ),
        "portfolio_pf":
            round(
                s["profit_factor"],
                9,
            ),
        "portfolio_total_r":
            round(
                s["total_r"],
                6,
            ),
        "portfolio_expectancy_r":
            round(
                s["expectancy_r"],
                9,
            ),
        "portfolio_ending_balance_1pct":
            round(
                c["ending_balance"],
                6,
            ),
        "portfolio_return_pct_1pct":
            round(
                c["return_pct"],
                6,
            ),
        "portfolio_max_closed_equity_dd_pct":
            round(
                c[
                    "max_closed_equity_dd_pct"
                ],
                6,
            ),

        "delta_pf_vs_current":
            round(
                s["profit_factor"]
                - baseline_metrics[
                    "profit_factor"
                ],
                9,
            ),
        "delta_total_r_vs_current":
            round(
                s["total_r"]
                - baseline_metrics[
                    "total_r"
                ],
                6,
            ),
        "delta_expectancy_vs_current":
            round(
                s["expectancy_r"]
                - baseline_metrics[
                    "expectancy_r"
                ],
                9,
            ),
        "delta_ending_balance_vs_current":
            round(
                c["ending_balance"]
                - baseline_metrics[
                    "ending_balance"
                ],
                6,
            ),
        "delta_dd_pct_vs_current":
            round(
                c[
                    "max_closed_equity_dd_pct"
                ]
                - baseline_metrics[
                    "max_closed_equity_dd_pct"
                ],
                6,
            ),
    }


def baseline_metrics(df):
    s = simple_stats(df)
    c = compound(df)

    return {
        "profit_factor":
            s["profit_factor"],
        "total_r":
            s["total_r"],
        "expectancy_r":
            s["expectancy_r"],
        "ending_balance":
            c["ending_balance"],
        "max_closed_equity_dd_pct":
            c[
                "max_closed_equity_dd_pct"
            ],
    }


# ============================================================
# RUN
# ============================================================

def run_research():
    try:
        STATUS.update({
            "state":
                "fetching_h1",
            "message":
                "Fetching GBP/USD H1 history",
        })

        h1 = fetch_h1()

        if not h1:
            raise RuntimeError(
                "No H1 candles returned"
            )

        STATUS.update({
            "state":
                "precomputing",
            "message":
                "Precomputing exact bullish-engulfing features",
        })

        atr = atr_series(h1)

        raw_candidates = (
            build_raw_candidates(
                h1,
                atr,
            )
        )

        base5 = read_baseline(
            BASE5
        )

        base2 = read_baseline(
            BASE2
        )

        baseline5 = (
            baseline_metrics(
                base5
            )
        )

        baseline2 = (
            baseline_metrics(
                base2
            )
        )

        rows5 = []
        rows2 = []
        candidate_trade_exports = []

        STATUS.update({
            "state":
                "running",
            "message":
                "Testing GBP/USD alternatives in portfolio",
            "completed":
                0,
        })

        for number, cfg in enumerate(
            CONFIGS,
            start=1,
        ):
            trades = simulate_config(
                h1,
                raw_candidates,
                cfg,
            )

            incoming = candidate_df(
                trades
            )

            candidate_trade_exports.extend([
                {
                    "candidate_id":
                        cfg["id"],
                    "signal_time":
                        trade[
                            "signal_time"
                        ].isoformat(),
                    "exit_time":
                        trade[
                            "exit_time"
                        ].isoformat(),
                    "reference_entry":
                        trade[
                            "reference_entry"
                        ],
                    "backtest_entry":
                        trade[
                            "backtest_entry"
                        ],
                    "stop":
                        trade["stop"],
                    "target":
                        trade["target"],
                    "exit_reason":
                        trade[
                            "exit_reason"
                        ],
                    "result_r":
                        trade["result_r"],
                }
                for trade in trades
            ])

            for (
                window,
                baseline,
                base_metrics,
                collector,
            ) in [
                (
                    "5Y",
                    base5,
                    baseline5,
                    rows5,
                ),
                (
                    "2Y",
                    base2,
                    baseline2,
                    rows2,
                ),
            ]:
                start = baseline[
                    "entry_time_utc"
                ].min()

                end = baseline[
                    "entry_time_utc"
                ].max()

                incoming_window = (
                    restrict_window(
                        incoming,
                        start,
                        end,
                    )
                )

                proposed = substitute(
                    baseline,
                    incoming,
                )

                collector.append(
                    portfolio_row(
                        window,
                        cfg,
                        proposed,
                        len(
                            incoming_window
                        ),
                        base_metrics,
                    )
                )

            STATUS[
                "completed"
            ] = number

            print(
                f"Alternative "
                f"{number}/"
                f"{len(CONFIGS)}: "
                f"{cfg['id']}",
                flush=True,
            )

        df5 = pd.DataFrame(
            rows5
        )

        df2 = pd.DataFrame(
            rows2
        )

        # 5Y is the primary ranking.
        df5 = (
            df5.sort_values(
                by=[
                    "portfolio_ending_balance_1pct",
                    "portfolio_total_r",
                    "portfolio_pf",
                    "portfolio_expectancy_r",
                    "portfolio_max_closed_equity_dd_pct",
                ],
                ascending=[
                    False,
                    False,
                    False,
                    False,
                    False,
                ],
            )
            .reset_index(
                drop=True
            )
        )

        df5[
            "rank_5y"
        ] = (
            df5.index
            + 1
        )

        df2 = (
            df2.sort_values(
                by=[
                    "portfolio_ending_balance_1pct",
                    "portfolio_total_r",
                    "portfolio_pf",
                    "portfolio_expectancy_r",
                    "portfolio_max_closed_equity_dd_pct",
                ],
                ascending=[
                    False,
                    False,
                    False,
                    False,
                    False,
                ],
            )
            .reset_index(
                drop=True
            )
        )

        df2[
            "rank_2y"
        ] = (
            df2.index
            + 1
        )

        merged = df5.merge(
            df2[
                [
                    "candidate_id",
                    "rank_2y",
                    "portfolio_ending_balance_1pct",
                    "portfolio_total_r",
                    "portfolio_pf",
                    "portfolio_expectancy_r",
                    "portfolio_max_closed_equity_dd_pct",
                    "delta_ending_balance_vs_current",
                    "delta_total_r_vs_current",
                ]
            ],
            on="candidate_id",
            suffixes=(
                "_5y",
                "_2y",
            ),
        )

        # A useful balanced rank: lower is better.
        merged[
            "combined_rank_score"
        ] = (
            merged[
                "rank_5y"
            ]
            + merged[
                "rank_2y"
            ]
        )

        merged = (
            merged.sort_values(
                by=[
                    "combined_rank_score",
                    "rank_5y",
                    "rank_2y",
                ],
                ascending=[
                    True,
                    True,
                    True,
                ],
            )
            .reset_index(
                drop=True
            )
        )

        df5.to_csv(
            os.path.abspath(
                OUTPUT_RANKING_5Y
            ),
            index=False,
        )

        df2.to_csv(
            os.path.abspath(
                OUTPUT_RANKING_2Y
            ),
            index=False,
        )

        merged.to_csv(
            os.path.abspath(
                OUTPUT_SUMMARY
            ),
            index=False,
        )

        pd.DataFrame(
            candidate_trade_exports
        ).to_csv(
            os.path.abspath(
                OUTPUT_TRADES
            ),
            index=False,
        )

        STATUS.update({
            "state":
                "complete",
            "message":
                "GBP/USD portfolio replacement shootout complete",
            "alternatives":
                len(CONFIGS),
            "outputs": {
                "summary":
                    OUTPUT_SUMMARY,
                "5y":
                    OUTPUT_RANKING_5Y,
                "2y":
                    OUTPUT_RANKING_2Y,
                "trades":
                    OUTPUT_TRADES,
            },
        })

        print()
        print(
            "=" * 100
        )
        print(
            "GBP/USD PORTFOLIO REPLACEMENT SHOOTOUT COMPLETE"
        )
        print(
            "=" * 100
        )

        print(
            merged.head(
                10
            ).to_string(
                index=False
            ),
            flush=True,
        )

    except Exception as error:
        STATUS.update({
            "state":
                "error",
            "message":
                str(error),
        })

        print(
            "ERROR:",
            error,
            flush=True,
        )


