@app.route("/status")
def status():
    return jsonify(
        STATUS
    )


def send_output(filename):
    path = os.path.abspath(
        filename
    )

    if not os.path.exists(
        path
    ):
        return jsonify({
            "status":
                "not_ready",
            "message":
                f"{filename} is not ready yet",
        }), 404

    return send_file(
        path,
        as_attachment=True,
        download_name=filename,
    )


@app.route(
    "/download/summary"
)
def download_summary():
    return send_output(
        OUTPUT_SUMMARY
    )


@app.route(
    "/download/5y"
)
def download_5y():
    return send_output(
        OUTPUT_RANKING_5Y
    )


@app.route(
    "/download/2y"
)
def download_2y():
    return send_output(
        OUTPUT_RANKING_2Y
    )


@app.route(
    "/download/trades"
)
def download_trades():
    return send_output(
        OUTPUT_TRADES
    )


