    thread = threading.Thread(
        target=run_research,
        name=(
            "gbpusd-portfolio-replacement-shootout"
        ),
        daemon=True,
    )

    thread.start()

    port = int(
        os.getenv(
            "PORT",
            5000,
        )
    )

    app.run(
        host="0.0.0.0",
        port=port,
        debug=False,
    )
